#include "source_mario_set_direction.hpp"
#include <cassert>
#include <cmath>
#include <cstring>
#include <map>
#include <string>
#include <vector>
#include <iostream>
using namespace ttyd;
namespace {
uint32_t bits(float f){uint32_t v;std::memcpy(&v,&f,4);return v;}float scalar(uint32_t v){float f;std::memcpy(&f,&v,4);return f;}
constexpr uint32_t MP=0x8041e900,A=0x6000,B=0x7000,E=0x8000,ARGS=0x9000;
struct World{
 std::shared_ptr<const void>life=std::make_shared<int>(1);std::map<uint32_t,uint32_t>w;std::vector<std::string>trace;size_t index=0,stall=~size_t(0);int waits=0;bool alive=true,late=false,reenter=false;SourceMarioSetDirection*active=nullptr;
 EventEntry event{};
 World(){event.id=5;event.currentCommand=0x905065e4;w[MP]=A;w[E+0x18]=ARGS;w[ARGS]=bits(90);w[ARGS+4]=100;w[ARGS+8]=0;w[0x80415fd0]=0xa000;w[0xa004]=60;w[E+0x78]=0;w[E+0x80]=0;w[E+0x7c]=bits(270);w[A+0x1ac]=bits(270);w[A+0x19c]=bits(0);w[B+0x19c]=bits(60);
 for(auto pair:{std::pair<uint32_t,float>{0x80420a60,0},{0x80420a68,360},{0x80420a90,270},{0x80420a88,.5},{0x80420a8c,-.5},{0x80420a94,1000},{0x80421b1c,270},{0x80421b44,360},{0x80421adc,0}})w[pair.first]=bits(pair.second);}
 bool admit(){if(reenter){reenter=false;assert(active);assert(!active->reset());assert(!active->resume(event,E,false,services()));}if(index==stall&&waits++<2)return false;++index;return true;}
 static bool current(void*p){return static_cast<World*>(p)->alive;}
 static std::optional<uint32_t>word(void*p,uint32_t a){auto&x=*static_cast<World*>(p);if(!x.admit())return {};if(!x.w.count(a))return {};auto v=x.w[a];x.trace.push_back("R"+std::to_string(a)+":"+std::to_string(v));return v;}
 static std::optional<uint64_t>wide(void*p,uint32_t a){auto&x=*static_cast<World*>(p);if(!x.admit())return {};assert(a==0x802c3ec0||a==0x802e3eb8);x.trace.push_back("D"+std::to_string(a));return 0x4330000080000000ULL;}
 static bool store(void*p,uint32_t a,uint32_t v){auto&x=*static_cast<World*>(p);if(!x.admit())return false;x.trace.push_back("W"+std::to_string(a)+":"+std::to_string(v));x.w[a]=v;if(x.late&&a==A+0x1ac){x.w[a]=bits(32);x.w[MP]=B;}if(x.late&&a==A+0x1a4)x.w[a]=bits(123);return true;}
 static std::optional<float>eventFloat(void*p,EventEntry&,uint32_t v){auto&x=*static_cast<World*>(p);if(!x.admit())return {};x.trace.push_back("F"+std::to_string(v));return scalar(v);}
 static std::optional<int32_t>eventValue(void*p,EventEntry&,uint32_t v){auto&x=*static_cast<World*>(p);if(!x.admit())return {};x.trace.push_back("V"+std::to_string(v));return int32_t(v);}
 static std::optional<float>number(void*p,const SourceMarioDirectionNumber&q){auto&x=*static_cast<World*>(p);if(!x.admit())return {};x.trace.push_back("N"+std::to_string(q.callsite)+":"+std::to_string(bits(q.values[0]))+":"+std::to_string(bits(q.values[1]))+":"+std::to_string(bits(q.values[2]))+":"+std::to_string(q.word));switch(q.kind){case SourceMarioDirectionNumberKind::Add:return q.values[0]+q.values[1];case SourceMarioDirectionNumberKind::Subtract:return q.values[0]-q.values[1];case SourceMarioDirectionNumberKind::Multiply:return q.values[0]*q.values[1];case SourceMarioDirectionNumberKind::Divide:return q.values[0]/q.values[1];case SourceMarioDirectionNumberKind::FusedMultiplyAdd:return std::fma(q.values[0],q.values[1],q.values[2]);case SourceMarioDirectionNumberKind::SignedWordMinusDouble:{double d;std::memcpy(&d,&q.doubleBits,8);uint64_t value=0x4330000000000000ULL|(q.word^0x80000000u);double raw;std::memcpy(&raw,&value,8);return float(raw-d);}}return {};}
 static std::optional<int32_t>truncate(void*p,float v){auto&x=*static_cast<World*>(p);if(!x.admit())return {};x.trace.push_back("T"+std::to_string(bits(v)));return int32_t(v);}
 SourceMarioDirectionServices services(){return {life,this,current,word,wide,store,eventFloat,eventValue,number,truncate};}
};using N=SourceMarioDirectionNumberKind;
float load(World&w,uint32_t a){return scalar(*World::word(&w,a));}float num(World&w,N k,uint32_t pc,float a=0,float b=0,float c=0,uint32_t v=0,uint64_t bias=0){return *World::number(&w,{k,pc,{a,b,c},v,bias});}
float helper(World&w,uint32_t fn,float input){float value=input,full,zero;if(fn==0x800961f8){auto actor=*World::word(&w,MP);auto half=load(w,0x80420a90);auto camera=load(w,actor+0x19c);auto d=num(w,N::Subtract,0x8009621c,half,input);zero=load(w,0x80420a60);value=num(w,N::Add,0x80096224,d,camera);auto round=load(w,value>=zero?0x80420a88:0x80420a8c);auto quantum=load(w,0x80420a94);value=num(w,N::FusedMultiplyAdd,0x80096250,quantum,value,round);auto bias=*World::wide(&w,0x802c3ec0);full=load(w,0x80420a68);auto integer=*World::truncate(&w,value);zero=load(w,0x80420a60);value=num(w,N::SignedWordMinusDouble,0x80096278,0,0,0,uint32_t(integer),bias);value=num(w,N::Divide,0x8009627c,value,quantum);}else{full=load(w,0x80420a68);zero=load(w,0x80420a60);}while(value<zero)value=num(w,N::Add,fn==0x800961f8?0x80096284:0x80096570,value,full);full=load(w,0x80420a68);while(value>=full)value=num(w,N::Subtract,fn==0x800961f8?0x80096298:0x80096584,value,full);return value;}
int reference(World&w,bool first){auto args=*World::word(&w,E+0x18);auto a=*World::word(&w,MP);auto target=*World::eventFloat(&w,w.event,*World::word(&w,args));auto ms=*World::eventValue(&w,w.event,*World::word(&w,args+4));auto gp=*World::word(&w,0x80415fd0);auto hz=*World::word(&w,gp+4);int32_t product=int32_t(uint32_t(ms)*hz);int64_t hi=(int64_t(product)*0x10624dd3)>>32;int64_t shifted=hi>>6;auto frames=int32_t(shifted+(shifted<0));auto mode=*World::eventValue(&w,w.event,*World::word(&w,args+8));if(first){auto h=load(w,0x80421b1c);World::store(&w,E+0x78,0);World::store(&w,E+0x80,0);auto initial=load(w,a+0x1ac);World::store(&w,E+0x7c,bits(initial));if(target>h)target=num(w,N::Subtract,0x800e6e80,target,load(w,0x80421b44));}auto latch=*World::word(&w,E+0x80);if(latch==1){auto z=load(w,0x80421adc);World::store(&w,a+0x1a4,bits(z));World::store(&w,a+0x1a0,bits(z));return 2;}
 float angle;if(frames>0){angle=num(w,N::Subtract,0x800e6eb0,load(w,0x80421b1c),target);angle=helper(w,0x80096564,angle);if(angle>load(w,0x80421b1c))angle=num(w,N::Subtract,0x800e6ec8,angle,load(w,0x80421b44));auto counter=*World::word(&w,E+0x78);auto initial=load(w,E+0x7c);auto bias=*World::wide(&w,0x802e3eb8);auto d=num(w,N::Subtract,0x800e6eec,angle,initial);auto count=num(w,N::SignedWordMinusDouble,0x800e6efc,0,0,0,counter,bias);auto total=num(w,N::SignedWordMinusDouble,0x800e6f08,0,0,0,uint32_t(frames),bias);auto ratio=num(w,N::Divide,0x800e6f0c,count,total);auto movement=num(w,N::Multiply,0x800e6f10,d,ratio);angle=num(w,N::Add,0x800e6f14,initial,movement);}else angle=num(w,N::Subtract,0x800e6f74,load(w,0x80421b1c),target);
 angle=helper(w,0x80096564,angle);World::store(&w,a+0x1ac,bits(angle));auto v=load(w,a+0x1ac);World::store(&w,a+0x1b0,bits(v));v=load(w,a+0x1ac);v=helper(w,0x800961f8,v);World::store(&w,a+0x1a4,bits(v));v=load(w,a+0x1a4);World::store(&w,a+0x1a0,bits(v));if(frames<=0)return 2;auto counter=*World::word(&w,E+0x78)+1;World::store(&w,E+0x78,counter);if(int32_t(counter)>frames){if(mode==0)return 1;World::store(&w,E+0x80,1);}return 0;}
void parity(){for(bool first:{false,true})for(int duration:{-100,0,100,0x40000000})for(int mode:{0,1})for(float angle:{90.f,270.f,-450.f})for(bool late:{false,true}){World ref;ref.w[ARGS]=bits(angle);ref.w[ARGS+4]=uint32_t(duration);ref.w[ARGS+8]=mode;ref.w[E+0x78]=9;ref.late=late;int result=reference(ref,first);for(size_t wait=0;wait<=ref.index;++wait){World w;w.w[ARGS]=bits(angle);w.w[ARGS+4]=uint32_t(duration);w.w[ARGS+8]=mode;w.w[E+0x78]=9;w.late=late;w.stall=wait;SourceMarioSetDirection owner;w.active=&owner;w.reenter=true;std::optional<int32_t>got;unsigned n=0;do{got=owner.resume(w.event,E,n==0?first:false,w.services());assert(++n<10);}while(!got);assert(*got==result&&w.trace==ref.trace&&w.w==ref.w);auto count=w.index;assert(owner.resume(w.event,E,false,w.services())==got&&w.index==count);}}
}
void visits(){World w;SourceMarioSetDirection owner;std::vector<int>results;for(unsigned i=0;i<8;++i){auto got=owner.resume(w.event,E,i==0,w.services());assert(got);results.push_back(*got);assert(owner.reset());if(*got==1)break;}assert(results==std::vector<int>({0,0,0,0,0,0,1}));w.w[ARGS+8]=1;for(unsigned i=0;i<9;++i){auto got=owner.resume(w.event,E,i==0,w.services());assert(got);assert(owner.reset());if(i<7)assert(*got==0);else{assert(*got==2);break;}}
}
void guards(){World w;SourceMarioSetDirection c;auto s=w.services();s.eventValue=nullptr;assert(!c.resume(w.event,E,true,s));assert(c.pending()==0x80031260);auto count=w.index;auto swapped=s;swapped.word=nullptr;assert(!c.resume(w.event,E,true,swapped)&&w.index==count);w.alive=false;assert(!c.resume(w.event,E,true,s));w.alive=true;assert(!c.resume(w.event,E,true,s)&&w.index==count);assert(!c.reset());World h;SourceMarioDirectionHelper helperOwner;auto hs=h.services();hs.number=nullptr;assert(!helperOwner.resume(0x800961f8,90,hs)&&helperOwner.pending()==0x8009621c);}
}
int main(){parity();visits();guards();std::cout<<"Whole SetDir/Revise360/ToMovedir/sysMsec2Frame traces, every wait twice, actual polling and fresh actor/angle reads pass\n";return 0;}
